#include <cstdint>

#include <poppler-global.h>
#include <poppler-document.h>
#include <poppler-page.h>
#include <poppler-page-renderer.h>

static void nop_func(const std::string& msg, void*) {};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  poppler::set_debug_error_function(nop_func, nullptr);

  poppler::document *doc = poppler::document::load_from_raw_data((const char *)data, size);
  if (!doc || doc->is_locked()) {
    delete doc;
    return 0;
  }

  poppler::page_renderer r;
  for (int i = 0; i < doc->pages(); i++) {
    poppler::page *p = doc->create_page(i);
    if (!p) {
      continue;
    }
    r.render_page(p);
    delete p;
  }

  delete doc;
  return 0;
}

---BUILD---

pushd $SRC/freetype2
./autogen.sh
./configure --prefix="$WORK" --disable-shared PKG_CONFIG_PATH="$WORK/lib/pkgconfig"
make -j$(nproc)
make install
mkdir -p $WORK/poppler
pushd $WORK/poppler
cmake $SRC/poppler   -DCMAKE_BUILD_TYPE=debug   -DBUILD_SHARED_LIBS=OFF   -DFONT_CONFIGURATION=generic   -DENABLE_DCTDECODER=none   -DENABLE_LIBOPENJPEG=none   -DENABLE_CMS=none   -DENABLE_LIBPNG=OFF   -DENABLE_ZLIB=OFF   -DENABLE_LIBTIFF=OFF   -DENABLE_LIBJPEG=OFF   -DENABLE_GLIB=OFF   -DENABLE_LIBCURL=OFF   -DENABLE_QT5=OFF   -DENABLE_UTILS=OFF   -DWITH_Cairo=OFF   -DWITH_NSS3=OFF   -DFREETYPE_INCLUDE_DIRS=$WORK/include/freetype2   -DFREETYPE_LIBRARY=$WORK/lib
make -j$(nproc) poppler poppler-cpp
fuzz_target=pdf_fuzzer
pushd $SRC/poppler
$CXX $CXXFLAGS -std=c++11 -Icpp     fuzz/pdf_fuzzer.cc -o $OUT/$fuzz_target     -lFuzzingEngine $WORK/poppler/cpp/libpoppler-cpp.a $WORK/poppler/libpoppler.a $WORK/lib/libfreetype.a
mv $SRC/{*.zip,*.dict} $OUT
if [ ! -f "${OUT}/${fuzz_target}_seed_corpus.zip" ]; then
  echo "missing seed corpus"
  exit 1
fi
if [ ! -f "${OUT}/${fuzz_target}.dict" ]; then
  echo "missing dictionary"
  exit 1
fi

